alter table public.bill_payments drop constraint if exists bill_payments_status_check;
alter table public.bill_payments add constraint bill_payments_status_check check(status in('unpaid','pending_verification','paid','not_received','rejected'));
alter table public.bill_payments add column if not exists payment_reference text;
alter table public.bill_payments add column if not exists covered_through date;
alter table public.bill_payments add column if not exists request_sequence integer;
create unique index if not exists bill_payments_payment_reference_key on public.bill_payments(payment_reference) where payment_reference is not null;
create index if not exists bill_payments_bill_created_idx on public.bill_payments(bill_id,created_at);
update public.bill_payments p set payment_reference='GoCanteen-'||coalesce(m.bill_year::text,'0000')||'-'||lpad(coalesce(m.bill_month,0)::text,2,'0')||'-'||left(p.id::text,8) from public.monthly_bills m where m.id=p.bill_id and nullif(btrim(p.payment_reference),'') is null;
update public.bill_payments p set covered_through=coalesce(p.covered_through,m.billing_end_date) from public.monthly_bills m where m.id=p.bill_id;
create or replace function public.publish_employee_bill(p_employee_id uuid,p_month integer,p_year integer,p_food_total numeric,p_admin_added_total numeric,p_guest_food_total numeric default 0,p_days_ordered integer default 0,p_billing_start_date date default null,p_billing_end_date date default null) returns public.monthly_bills language plpgsql security definer set search_path=public as $$ declare a public.profiles%rowtype;e public.profiles%rowtype;b public.monthly_bills%rowtype;n timestamptz:=now();total numeric:=greatest(coalesce(p_food_total,0),0)+greatest(coalesce(p_admin_added_total,0),0);represented numeric:=0;requestable numeric:=0;seq integer:=1;pid uuid;ref text;begin select * into a from public.profiles where id=auth.uid() and role='admin' and status='active' and canteen_id=public.current_canteen_id();if not found then raise exception 'Admin authorization required';end if;select * into e from public.profiles where id=p_employee_id and role='employee' and canteen_id=public.current_canteen_id();if not found then raise exception 'Employee not found in current canteen';end if;insert into public.monthly_bills(employee_id,bill_month,bill_year,billing_start_date,billing_end_date,days_ordered,food_total,guest_food_total,admin_added_total,total,published,published_at,updated_at,canteen_id) values(p_employee_id,p_month,p_year,coalesce(p_billing_start_date,make_date(p_year,p_month,1)),coalesce(p_billing_end_date,(make_date(p_year,p_month,1)+interval '1 month - 1 day')::date),greatest(coalesce(p_days_ordered,0),0),greatest(coalesce(p_food_total,0),0),greatest(coalesce(p_guest_food_total,0),0),greatest(coalesce(p_admin_added_total,0),0),total,true,n,n,public.current_canteen_id()) on conflict(employee_id,bill_month,bill_year) do update set billing_start_date=excluded.billing_start_date,billing_end_date=excluded.billing_end_date,days_ordered=excluded.days_ordered,food_total=excluded.food_total,guest_food_total=excluded.guest_food_total,admin_added_total=excluded.admin_added_total,total=excluded.total,published=true,published_at=excluded.published_at,updated_at=excluded.updated_at returning * into b;select coalesce(sum(amount),0) into represented from public.bill_payments where bill_id=b.id and employee_id=b.employee_id and canteen_id=b.canteen_id and status in('paid','pending_verification','unpaid','rejected','not_received');requestable:=greatest(total-represented,0);select coalesce(max(request_sequence),0)+1 into seq from public.bill_payments where bill_id=b.id;if requestable>0 then pid:=gen_random_uuid();ref:='GoCanteen-'||p_year||'-'||lpad(p_month::text,2,'0')||'-'||left(b.employee_id::text,8)||'-B'||seq||'-'||left(pid::text,8);insert into public.bill_payments(id,bill_id,employee_id,amount,status,created_at,updated_at,canteen_id,payment_reference,covered_through,request_sequence) values(pid,b.id,b.employee_id,requestable,'unpaid',n,n,b.canteen_id,ref,b.billing_end_date,seq);end if;return b;end;$$;
revoke all on function public.publish_employee_bill(uuid,integer,integer,numeric,numeric,numeric,integer,date,date) from public;grant execute on function public.publish_employee_bill(uuid,integer,integer,numeric,numeric,numeric,integer,date,date) to authenticated;
drop function if exists public.confirm_bill_payment(uuid);
create or replace function public.confirm_bill_payment(p_payment_id uuid) returns public.bill_payments language plpgsql security definer set search_path=public as $$ declare p public.bill_payments%rowtype;begin select * into p from public.bill_payments where id=p_payment_id and employee_id=auth.uid() and canteen_id=public.current_canteen_id();if not found then raise exception 'Payment request not found or not accessible';end if;if p.status='pending_verification' then return p;end if;if p.status not in('unpaid','not_received','rejected') then raise exception 'Payment request is not payable in its current status';end if;update public.bill_payments set status='pending_verification',confirmed_at=now(),updated_at=now() where id=p.id returning * into p;return p;end;$$;
revoke all on function public.confirm_bill_payment(uuid) from public;grant execute on function public.confirm_bill_payment(uuid) to authenticated;
